39	impl Debug for ValueNumber {
40	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
41	        match self {
42	            Self::Top => write!(f, "Top"),
43	            Self::Number(arg0) => write!(f, "v{:?}", arg0.0.data()),
44	        }
45	    }
46	}
