156	#[derive(Default)]
157	struct VNTable {
158	    value_map: FxHashMap<Value, ValueNumber>,
159	    expr_map: FxHashMap<Expr, ValueNumber>,
160	}
161	
162	impl Debug for VNTable {
163	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
164	        writeln!(f, "value_map:")?;
165	        self.value_map.iter().for_each(|(key, value)| {
166	            if format!("v{:?}", key.0.data()) == "v620v3" {
167	                writeln!(f, "\tv{:?} -> {:?}", key.0.data(), value).expect("writeln! failed");
168	            }
169	        });
170	        Ok(())
171	    }
172	}
