209	pub fn cse(
210	    context: &mut Context,
211	    analyses: &AnalysisResults,
212	    function: Function,
213	) -> Result<bool, IrError> {
214	    let mut vntable = VNTable::default();
215	
216	    // Function arg values map to themselves.
217	    for arg in function.args_iter(context) {
218	        vntable.value_map.insert(arg.1, ValueNumber::Number(arg.1));
219	    }
